import asyncio
import functools
from fastapi import FastAPI, Depends
from fastapi.testclient import TestClient

app = FastAPI()

# Case 1: Regular function wrapped by async wrapper
def regular_func():
    return "regular"

def async_wrapper(func):
    @functools.wraps(func)
    async def wrapper(*args, **kwargs):
        return await func(*args, **kwargs) if asyncio.iscoroutinefunction(func) else func(*args, **kwargs)
    return wrapper

wrapped_regular = async_wrapper(regular_func)

# Case 2: Async function wrapped by regular wrapper
async def async_func():
    return "async"

def regular_wrapper(func):
    @functools.wraps(func)
    def wrapper(*args, **kwargs):
        return func(*args, **kwargs)
    return wrapper

wrapped_async = regular_wrapper(async_func)

# Case 3: Partial of async function
partial_async = functools.partial(async_func)

# Case 4: Partial of regular function wrapped by async wrapper
partial_regular = functools.partial(regular_func)
wrapped_partial_regular = async_wrapper(partial_regular)

@app.get("/case1")
async def case1():
    return await wrapped_regular()

@app.get("/case2")
async def case2():
    # This might fail if FastAPI doesn't detect it's async because of the regular wrapper
    return await wrapped_async()

@app.get("/case3")
async def case3():
    # This might fail if FastAPI doesn't detect partial as async
    return await partial_async()

@app.get("/case4")
async def case4():
    return await wrapped_partial_regular()

client = TestClient(app)

def test_cases():
    try:
        print("Testing Case 1...")
        assert client.get("/case1").json() == "regular"
        print("Case 1 passed")

        print("Testing Case 2...")
        assert client.get("/case2").json() == "async"
        print("Case 2 passed")

        print("Testing Case 3...")
        assert client.get("/case3").json() == "async"
        print("Case 3 passed")

        print("Testing Case 4...")
        assert client.get("/case4").json() == "regular"
        print("Case 4 passed")
    except Exception as e:
        print(f"Error: {e}")
        import traceback
        traceback.print_exc()

if __name__ == "__main__":
    test_cases()
